function oneOff(a,b){if(a===b)return true;if(a[0]!==b[0])return false;if(Math.abs(a.length-b.length)>1||a.length<5)return false;var i=0,j=0,d=0;while(i<a.length&&j<b.length){if(a[i]===b[j]){i++;j++;continue}if(++d>1)return false;if(a.length>b.length)i++;else if(a.length<b.length)j++;else{i++;j++}}return d+(a.length-i)+(b.length-j)<=1;}
function hit(t,w){if(w.trim().length<=4&&w.trim().indexOf(" ")<0)return t.indexOf(" "+w.trim()+" ")>-1;if(t.indexOf(" "+w)>-1)return true;if(w.indexOf(" ")>-1||w.length<7)return false;return t.trim().split(" ").some(function(x){return oneOff(x.slice(0,w.length),w)||oneOff(x,w)});}
